"""Pre-registered formal versions V51--V90.

This module is deliberately a registry only.  It contains no feature builder,
model fitting, result reader, or execution hook.  These versions are formal
candidate versions, not a cross-version screening list.  When execution is
authorized, each version independently builds its own pool, freezes its own
Development+Validation Top1, and evaluates its own Test.  The exact
implementation/grid must be frozen in the version method card before running.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass


@dataclass(frozen=True)
class ReserveVersionSpec:
    version: int
    core_logic_name: str
    title_cn: str
    family: str
    literature: str
    task_rewrite: str
    variants: tuple[str, ...]
    causal_guard: str
    main_risk: str
    priority: str

    @property
    def version_id(self) -> str:
        return f"V{self.version:02d}"

    def as_dict(self) -> dict:
        return asdict(self) | {"version_id": self.version_id}


